-- machine-library.js から自動生成。直接編集せず scripts/generate-ranking-rules.mjs を実行してください。
on conflict (machine_slug) do update set
  score_kind = excluded.score_kind,
  sim_kind = excluded.sim_kind,
  attempts_per_thousand = excluded.attempts_per_thousand,
  max_attempts = excluded.max_attempts,
  max_payout = excluded.max_payout,
  allowed_settings = excluded.allowed_settings,
  updated_at = now();
